// The PSD importer, run in a real browser against a real PSD.
//
// It has to be a browser: parsing happens client-side so a 200MB file never
// crosses the network, and the work is canvas work — masks baked into alpha,
// a group of letter shapes composited back into one logo. None of that can be
// checked in Node without a native image library on the runner.
//
// The fixture is generated by psd-fixture.mjs and reproduces what October's
// own Adobe Express exports actually do. Each assertion below maps to
// something observed in a real file that produces a visibly wrong import if
// handled naively.
//
//   npm run test:browser

import { chromium } from 'playwright';
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';

const here = path.dirname(fileURLToPath(import.meta.url));
const dist = path.join(here, 'dist');

if (!fs.existsSync(path.join(dist, 'psd.html'))) {
  console.error('No build to test. Run: npx vite build --config tests/browser/vite.config.js');
  process.exit(1);
}

// Generate the fixture into the served directory rather than committing a
// binary: the generator is readable, the PSD is not.
execFileSync(process.execPath, [path.join(here, 'psd-fixture.mjs'), path.join(dist, 'fixture.psd')]);

const TYPES = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css',
  '.psd': 'application/octet-stream', '.json': 'application/json' };
const server = http.createServer((req, res) => {
  const rel = decodeURIComponent(req.url.split('?')[0]).replace(/^\/+/, '') || 'psd.html';
  const file = path.join(dist, rel);
  if (!file.startsWith(dist) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) {
    res.writeHead(404).end('not found');
    return;
  }
  res.writeHead(200, { 'Content-Type': TYPES[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const origin = `http://127.0.0.1:${server.address().port}`;

let pass = 0;
let fail = 0;
const check = (name, ok, detail) => {
  if (ok) { pass += 1; console.log('PASS ', name); }
  else { fail += 1; console.log('FAIL ', name, detail ? `\n  ${detail}` : ''); }
};

const browser = await chromium.launch({ executablePath: process.env.PW_CHROMIUM || undefined });
const page = await browser.newPage();
const problems = [];
page.on('pageerror', (e) => problems.push(`uncaught: ${e.message}`));

try {
  await page.goto(`${origin}/psd.html`, { waitUntil: 'networkidle' });
  await page.waitForFunction(() => window.__ready === true, { timeout: 10000 });

  const r = await page.evaluate(async () => {
    const res = await fetch('fixture.psd');
    const file = new File([await res.blob()], 'ADF AH&L 2026-6.psd');
    const parsed = await window.psdImport.parsePsd(file);

    // Read back the masked layer's pixels to prove the mask was applied.
    const masked = parsed.layers.find(l => l.name === 'Raster 4');
    let maskSample = null;
    if (masked) {
      const bmp = await createImageBitmap(masked.blob);
      const c = document.createElement('canvas');
      c.width = bmp.width; c.height = bmp.height;
      c.getContext('2d').drawImage(bmp, 0, 0);
      const px = (x, y) => c.getContext('2d').getImageData(x, y, 1, 1).data[3];
      maskSample = { kept: px(10, 10), cut: px(bmp.width - 10, 10) };
    }

    return {
      size: { w: parsed.width, h: parsed.height },
      names: parsed.layers.map(l => `${l.kind}:${l.name}`),
      logo: parsed.layers.find(l => l.name === 'Group'),
      scrim: parsed.layers.find(l => l.name === 'Rectangle'),
      headline: parsed.layers.find(l => l.kind === 'text' && /ARCHITECTURE TOUR/.test(l.text)),
      noSize: parsed.layers.find(l => l.kind === 'text' && /MA!/.test(l.text)),
      maskSample,
      notes: parsed.notes,
      // the fit, driven by a measure that is linear in size, as text is
      fitted: window.psdImport.fitFontSize(
        (s) => s * 0.6 * 'ARCHITECTURE TOUR:'.length, 694, 86.66666),
      fittedNoGuess: window.psdImport.fitFontSize(
        (s) => s * 0.6 * 'ARCHITECTURE TOUR:'.length, 694, null),
      font: window.psdImport.mapFont('GTAmerica-Bold'),
      resolved: window.psdImport.resolveFamily('GT America', ['Brockmann', 'GT America', 'Inter']),
    };
  });

  check('the page size comes through', r.size.w === 1080 && r.size.h === 1350);

  check('a hidden layer is skipped',
    !r.names.some(n => /Hidden thing/.test(n)), r.names.join(', '));

  // The one that turned a real file's 22 layers into 7.
  check('a wordmark of separate letter shapes becomes one logo',
    !!r.logo && r.logo.kind === 'image',
    `expected one image layer for the group; got ${r.names.join(', ')}`);
  check('and it sits at the union of its letters',
    r.logo && r.logo.left === 88 && r.logo.top === 774 && r.logo.width === 177 && r.logo.height === 23,
    r.logo && `${r.logo.left},${r.logo.top} ${r.logo.width}x${r.logo.height} — expected 88,774 177x23`);
  check('there are no stray Custom Shape layers left',
    !r.names.some(n => /Custom Shape/.test(n)));

  // Ignore the mask and the cut-out imports as the full rectangle it came from.
  check('a layer mask is baked into the image',
    r.maskSample && r.maskSample.kept > 200 && r.maskSample.cut === 0,
    r.maskSample && `kept alpha ${r.maskSample.kept}, cut alpha ${r.maskSample.cut}`);

  check('opacity is kept', r.scrim && Math.abs(r.scrim.opacity - 0.35) < 0.01,
    r.scrim && String(r.scrim.opacity));

  // Photoshop ends a line with \r. Miss it and the headline is one long line.
  check('a carriage-return line break becomes a real line break',
    r.headline && r.headline.text.split('\n').length === 2 && !/\r/.test(r.headline.text),
    r.headline && JSON.stringify(r.headline.text));
  check('and a blank line survives',
    r.noSize && r.noSize.text.split('\n').length === 3,
    r.noSize && JSON.stringify(r.noSize.text));

  check('the typeface and weight are read',
    r.font.family === 'GT America' && r.font.weight === 700 && r.font.italic === false,
    JSON.stringify(r.font));
  check('and resolved against the fonts the editor has',
    r.resolved === 'GT America', String(r.resolved));

  check('text colour is read', r.headline && r.headline.fill === 'rgb(254, 254, 254)',
    r.headline && r.headline.fill);

  // The reported size was right in one of October's files and a third too
  // large in another, and null in a third. The box is what can be trusted.
  check('type is fitted to the box, not to the reported size',
    Math.abs(r.fitted - 64.5) < 1.5,
    `fitted to ${r.fitted} for a 694px box; the reported 86.67 would overflow it`);
  check('and a missing size is fitted just the same',
    Math.abs(r.fittedNoGuess - r.fitted) < 1.5,
    `${r.fittedNoGuess} vs ${r.fitted}`);

  check('flattened effects are reported rather than silently dropped',
    r.notes.some(n => /effects/.test(n)), r.notes.join(' | '));

  // --- the whole path: parsed layers -> a scene the editor can open --------
  //
  // Built from numbers copied out of a real export (ADF AH&L 2026-6) rather
  // than from the fixture. ag-psd does not write bounds onto a text layer, so
  // a round-tripped fixture has none — and the bounds are exactly what the
  // scene builder has to get right, because the reported font size is wrong
  // as often as not. The fixture proves the parser; this proves the builder.
  const scene = await page.evaluate(async () => {
    const res = await fetch('fixture.psd');
    const file = new File([await res.blob()], 'ADF 2026-44.psd');
    const parsed = await window.psdImport.parsePsd(file);

    // Real layer, real numbers: 86.67 reported, in a box 694 wide.
    parsed.layers = parsed.layers.map(l => (
      /ARCHITECTURE/.test(l.text || '')
        ? { ...l, left: 89, top: 889, width: 694, height: 145, reportedSize: 86.66666 }
        : l));

    const { scene } = await window.psdImport.psdToScene(parsed, {
      uploadImage: async (layer) => URL.createObjectURL(layer.blob),
      ensureFont: async () => {},
      fonts: ['Brockmann', 'GT America', 'Inter'],
    });
    const objs = scene.objects || [];
    const headline = objs.find(o => /textbox/i.test(o.type) && /ARCHITECTURE/.test(o.text));
    return {
      canvas: { w: scene.width ?? null, h: scene.height ?? null },
      types: objs.map(o => String(o.type).toLowerCase()),
      count: objs.length,
      headline: headline && {
        left: Math.round(headline.left), top: Math.round(headline.top),
        width: Math.round(headline.width), fontSize: headline.fontSize,
        family: headline.fontFamily, weight: headline.fontWeight,
        fill: headline.fill, lines: headline.text.split('\n').length,
      },
      // the scrim, to prove opacity and placement survive serialisation
      scrim: (() => {
        const img = objs.filter(o => /image/i.test(o.type))
          .find(o => Math.round(o.top) === 899);
        return img && { top: Math.round(img.top), opacity: Math.round(img.opacity * 100) / 100 };
      })(),
      hasJsonSrc: objs.filter(o => /image/i.test(o.type)).every(o => typeof o.src === 'string'),
      // the fixture's other text layer, which really does arrive boundless
      noBounds: (() => {
        const o = objs.find(x => /textbox/i.test(x.type) && /MA!/.test(x.text));
        return o && { width: Math.round(o.width), fontSize: o.fontSize };
      })(),
    };
  });

  check('the scene is built as real Fabric objects',
    scene.types.filter(t => /textbox/.test(t)).length === 2
    && scene.types.filter(t => /image/.test(t)).length >= 3,
    `objects: ${scene.types.join(', ')}`);
  check('every image carries a source', scene.hasJsonSrc);
  check('the headline keeps its position and box',
    scene.headline && scene.headline.left === 89 && scene.headline.top === 889
    && Math.abs(scene.headline.width - 695) <= 2,
    JSON.stringify(scene.headline));
  check('it is sized to the box rather than to the reported 86.67',
    scene.headline && scene.headline.fontSize > 20 && scene.headline.fontSize < 80,
    scene.headline && `fontSize ${scene.headline.fontSize} — the reported 86.67 overflows a 694px box`);
  check('a text layer with no bounds still gets a real box',
    scene.noBounds && scene.noBounds.width > 50 && scene.noBounds.fontSize > 10,
    JSON.stringify(scene.noBounds));
  check('it keeps its weight, colour and two lines',
    scene.headline && scene.headline.weight === 700
    && scene.headline.fill === 'rgb(254, 254, 254)' && scene.headline.lines === 2,
    JSON.stringify(scene.headline));
  check('the scrim keeps its opacity through serialisation',
    scene.scrim && Math.abs(scene.scrim.opacity - 0.35) < 0.02,
    JSON.stringify(scene.scrim));

  // --- grouping a campaign's files into one set ----------------------------
  const naming = await page.evaluate(() => {
    const c = window.psdImport.commonName;
    const coll = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });
    return {
      // the five files October actually selected
      campaign: c(['ADF 2026-1.psd', 'ADF 2026-2.psd', 'ADF 2026-3.psd', 'ADF 2026-6.psd', 'ADF 2026-44.psd']),
      // a prefix that stops mid-number: the stray 0 is half an index
      midNumber: c(['Q4 launch 01.psd', 'Q4 launch 02.psd']),
      // a year at the end of a name is part of the name, not an index
      year: c(['Spring2026a.psd', 'Spring2026b.psd']),
      single: c(['ADF AH&L 2026-6.psd']),
      unrelated: c(['ADF 2026-44.psd', 'Caro spring-2.psd']),
      order: ['ADF 2026-44.psd', 'ADF 2026-6.psd', 'ADF 2026-1.psd'].sort((a, b) => coll.compare(a, b)),
    };
  });

  check("a campaign's files name their set",
    naming.campaign === 'ADF 2026', JSON.stringify(naming.campaign));
  check('a prefix that cuts a number in half is walked back',
    naming.midNumber === 'Q4 launch', JSON.stringify(naming.midNumber));
  check('but a year at the end of a name is kept',
    naming.year === 'Spring2026', JSON.stringify(naming.year));
  check('one file keeps its own name', naming.single === 'ADF AH&L 2026-6');
  check('unrelated files are not grouped',
    naming.unrelated === '', JSON.stringify(naming.unrelated));
  check('pages are ordered by number, not by string',
    naming.order.join() === 'ADF 2026-1.psd,ADF 2026-6.psd,ADF 2026-44.psd',
    naming.order.join(' '));

  // --- the round trip: PSD in, OMI, PSD out, read back ---------------------
  //
  // The point of the PSD export is that nothing made here is stuck here, and
  // the only honest way to check that is to read the export back with the
  // same parser that reads Photoshop's own files.
  const trip = await page.evaluate(async () => {
    const res = await fetch('fixture.psd');
    const parsed = await window.psdImport.parsePsd(
      new File([await res.blob()], 'ADF 2026-6.psd'));
    const { scene } = await window.psdImport.psdToScene(parsed, {
      uploadImage: async (l) => URL.createObjectURL(l.blob),
      ensureFont: async () => {},
      fonts: ['GT America'],
    });
    const size = { width: parsed.width, height: parsed.height };
    const bytes = await window.designExport.renderPsd(scene, size, { ensureFont: async () => {} });
    const back = await window.psdImport.parsePsd(
      new File([bytes], 'exported.psd', { type: 'image/vnd.adobe.photoshop' }));
    return {
      bytes: bytes.length,
      size: { w: back.width, h: back.height },
      layers: back.layers.length,
      wasLayers: parsed.layers.length,
      texts: back.layers.filter(l => l.kind === 'text').map(l => l.text),
      textFont: (back.layers.find(l => l.kind === 'text') || {}).family,
      images: back.layers.filter(l => l.kind === 'image').length,
      helpers: {
        order: [0, 9, 43].map(i => window.designExport.pageFilename('ADF 2026', i, 44, 'png')),
        font: window.designExport.psFontName('GT America', 700),
        hex: window.designExport.rgbOf('#f2c100'),
        rgba: window.designExport.rgbOf('rgba(0, 0, 0, 0.35)'),
      },
      zip: (await window.designExport.zipBlob({ 'a.png': new Uint8Array([1, 2, 3]) })).size,
    };
  });

  check('the exported PSD is a real file', trip.bytes > 1000, `${trip.bytes} bytes`);
  check('at the page size', trip.size.w === 1080 && trip.size.h === 1350, JSON.stringify(trip.size));
  check('with a layer per layer, not one flattened picture',
    trip.layers === trip.wasLayers,
    `${trip.wasLayers} went in, ${trip.layers} came back`);
  check('text comes back as text',
    trip.texts.some(t => /ARCHITECTURE TOUR/.test(t)),
    JSON.stringify(trip.texts));
  check('and keeps its line break',
    trip.texts.some(t => t.split('\n').length === 2), JSON.stringify(trip.texts));
  check('and its typeface',
    trip.textFont === 'GT America', String(trip.textFont));
  check('the images come back too', trip.images >= 2, String(trip.images));

  check('pages are named so they sort the way the set reads',
    trip.helpers.order[0].endsWith(' 01.png')
    && trip.helpers.order[1].endsWith(' 10.png')
    && trip.helpers.order[2].endsWith(' 44.png'),
    trip.helpers.order.join(' | '));
  check('a typeface is written back in the shape Photoshop expects',
    trip.helpers.font === 'GTAmerica-Bold', trip.helpers.font);
  check('colours convert from hex and from rgba',
    trip.helpers.hex.r === 242 && trip.helpers.hex.g === 193 && trip.helpers.hex.b === 0
    && trip.helpers.rgba.r === 0,
    JSON.stringify(trip.helpers));
  check('the zip is produced', trip.zip > 0, `${trip.zip} bytes`);

  check('nothing threw', problems.length === 0, problems.join('\n  '));
} catch (e) {
  fail += 1;
  console.log('FAIL  the run itself', `\n  ${e.message}`);
  if (problems.length) console.log(`  page problems:\n  ${problems.join('\n  ')}`);
}

await browser.close();
server.close();
console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
